import React from "react";
import {
  AbsoluteFill,
  spring,
  useCurrentFrame,
  useVideoConfig,
  delayRender,
  continueRender,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOutfit = makeLoadFont('Outfit');

// Initialize Google Fonts
const { fontFamily: outfitFamily } = loadOutfit();

// Initialize Custom Brand Fonts
if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const format = url.endsWith(".otf")
      ? "opentype"
      : url.endsWith(".woff2")
      ? "woff2"
      : url.endsWith(".woff")
      ? "woff"
      : "truetype";
    const font = new FontFace(family, `url('${url}') format('${format}')`);
    font
      .load()
      .then(() => {
        document.fonts.add(font);
        continueRender(handle);
      })
      .catch((err) => {
        console.log(`Error loading ${family}`, err);
        continueRender(handle);
      });
  };

  loadCustomFont(
    "Montserrat-Black",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/3088405d623049e09b5903534c39a29f.ttf"
  );
  loadCustomFont(
    "Montserrat-ExtraBold",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/9591a9df6f3b448cb5aead4a072dc3d4.ttf"
  );
  loadCustomFont(
    "Cormorant-MediumItalic",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/234e0f6ffdee4eba8ccb6b2a15cc3e0c.ttf"
  );
}

const resolveFont = (fontName: string) => {
  return fontName === "Outfit" ? outfitFamily : fontName;
};



export type HorizontalTrackAnimationProps = Record<string, any>;

const HorizontalTrackAnimation: React.FC<HorizontalTrackAnimationProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = true,
  durationInSeconds = 5,
  targetPosition = 0.8,
  rirNumber = "8",
  rirNumberColor = "#eae6d2",
  rirNumberFontFamily = "Montserrat-Black",
  leftLabel = "EASY",
  leftLabelColor = "#54412f",
  leftLabelFontFamily = "Montserrat-Black",
  rightLabel = "FAILURE",
  rightLabelColor = "#54412f",
  rightLabelFontFamily = "Montserrat-Black",
  trackColor = "#54412f",
  markerColor = "#eae6d2",
  animationSpeed = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Animation scaling calculations
  const speedAdjustedFrame = frame * animationSpeed;

  const trackScaleX = spring({
    frame: speedAdjustedFrame,
    fps,
    config: { damping: 16, stiffness: 100 },
  });

  const labelsScale = spring({
    frame: Math.max(0, speedAdjustedFrame - 10),
    fps,
    config: { damping: 14, stiffness: 120 },
  });

  const markerScale = spring({
    frame: Math.max(0, speedAdjustedFrame - 15),
    fps,
    config: { damping: 12, stiffness: 140 },
  });

  const slideSpring = spring({
    frame: Math.max(0, speedAdjustedFrame - 25),
    fps,
    config: { damping: 12, stiffness: 85 },
  });

  const slideProgressPercent = slideSpring * targetPosition * 100;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: "1400px",
          position: "relative",
          height: "100px",
          display: "flex",
          alignItems: "center",
        }}
      >
        {/* Track */}
        <div
          style={{
            width: "100%",
            height: "60px",
            backgroundColor: trackColor,
            borderRadius: "30px",
            transform: `scaleX(${trackScaleX})`,
            transformOrigin: "center",
          }}
        />

        {/* Left Label */}
        <div
          style={{
            position: "absolute",
            top: "120px",
            left: "0",
            transform: `scale(${labelsScale})`,
            transformOrigin: "top left",
            fontFamily: resolveFont(leftLabelFontFamily),
            fontSize: "65px",
            fontWeight: 900,
            color: leftLabelColor,
            textTransform: "uppercase",
            lineHeight: 1,
            transition: "none",
          }}
        >
          {leftLabel}
        </div>

        {/* Right Label */}
        <div
          style={{
            position: "absolute",
            top: "120px",
            right: "0",
            transform: `scale(${labelsScale})`,
            transformOrigin: "top right",
            fontFamily: resolveFont(rightLabelFontFamily),
            fontSize: "65px",
            fontWeight: 900,
            color: rightLabelColor,
            textTransform: "uppercase",
            lineHeight: 1,
            transition: "none",
          }}
        >
          {rightLabel}
        </div>

        {/* Moving Marker Container */}
        <div
          style={{
            position: "absolute",
            left: `${slideProgressPercent}%`,
            top: "50%",
            transform: `translate(-50%, -50%) scale(${markerScale})`,
            width: "100px",
            height: "100px",
            backgroundColor: markerColor,
            borderRadius: "50px",
            boxShadow: "0 15px 40px rgba(0,0,0,0.25)",
            transition: "none",
          }}
        >
          {/* RIR Number Attached to Marker */}
          <div
            style={{
              position: "absolute",
              bottom: "100%",
              left: "50%",
              transform: "translateX(-50%)",
              marginBottom: "35px",
              fontFamily: resolveFont(rirNumberFontFamily),
              fontSize: "220px",
              fontWeight: 900,
              color: rirNumberColor,
              lineHeight: 0.85,
              textAlign: "center",
              whiteSpace: "nowrap",
              transition: "none",
            }}
          >
            {rirNumber}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default HorizontalTrackAnimation;